import { cn } from "@/lib/utils";

// Same geometry as brand/mark.svg (generated by brand/make.py).
const C = "M73.04 29.26 A31 31 0 1 0 73.04 70.74";
export const CLOVE_PATH = "M50 8 C62 28 74 52 70 76 C68 90 32 90 30 76 C26 52 38 28 50 8Z";

/**
 * The clove mark: a lowercase c holding a clove. The c takes the text colour,
 * the clove stays bottle green unless `mono` is set.
 */
export function Glyph({ className, mono = false }: { className?: string; mono?: boolean }) {
  return (
    <svg viewBox="0 0 100 100" className={cn("size-4", className)} aria-hidden="true">
      <path d={C} fill="none" stroke="currentColor" strokeWidth="19" strokeLinecap="round" />
      <path
        d={CLOVE_PATH}
        transform="translate(53 51) rotate(16) scale(0.33) translate(-50 -49)"
        fill={mono ? "currentColor" : "var(--bottle)"}
      />
    </svg>
  );
}

/** The individual clove from the brand mark, used for a clone's petal. */
export function CloveGlyph({ className, angle = 0 }: { className?: string; angle?: number }) {
  return (
    <svg
      viewBox="24 4 52 88"
      className={cn("h-7 w-5", className)}
      style={{ transform: `rotate(${angle}deg)` }}
      aria-hidden="true"
    >
      <path
        className="clove-petal-body"
        d={CLOVE_PATH}
        fill="currentColor"
        fillOpacity="0.18"
        stroke="currentColor"
        strokeWidth="2.8"
        strokeLinejoin="round"
      />
      <path d="M50 24 C46 44 46 64 50 80" fill="none" stroke="currentColor" strokeWidth="1.5" opacity="0.45" />
    </svg>
  );
}

/** The clove alone, filled: a small symbol for clones (at icon sizes, where the outline would vanish). */
export function CloveMark({ className }: { className?: string }) {
  return (
    <svg viewBox="24 4 52 88" className={cn("size-4", className)} aria-hidden="true">
      <path d={CLOVE_PATH} fill="currentColor" />
    </svg>
  );
}
